Here is a small Node.js app that stores files outside the public web directory and checks passwords on the server before sending a download.

### 1. Install dependencies

```bash
mkdir file-share
cd file-share
npm init -y
npm install express multer bcrypt express-rate-limit
mkdir public
```

### 2. Create `server.js`

```js
const express = require("express");
const multer = require("multer");
const bcrypt = require("bcrypt");
const { rateLimit } = require("express-rate-limit");
const crypto = require("crypto");
const fs = require("fs/promises");
const path = require("path");

const app = express();
const dataDir = path.join(__dirname, "data");
const tempDir = path.join(dataDir, "temp");
const fileDir = path.join(dataDir, "files");

const upload = multer({
  dest: tempDir,
  limits: {
    fileSize: 100 * 1024 * 1024, // 100 MB
    files: 1,
  },
});

app.use(express.urlencoded({ extended: false, limit: "10kb" }));

// Only the public directory is served directly. Stored files are not.
app.use(express.static(path.join(__dirname, "public")));

app.post("/upload", upload.single("file"), async (req, res) => {
  const tempPath = req.file?.path;

  try {
    const password = req.body.password;

    if (!req.file || typeof password !== "string" || !password) {
      return res.status(400).json({ error: "Choose a file and password." });
    }

    // bcrypt uses at most 72 bytes of a password.
    if (Buffer.byteLength(password, "utf8") > 72) {
      return res.status(400).json({ error: "Password must be at most 72 bytes." });
    }

    const id = crypto.randomBytes(24).toString("hex");
    const passwordHash = await bcrypt.hash(password, 12);
    const storedPath = path.join(fileDir, id);

    await fs.rename(tempPath, storedPath);

    try {
      await fs.writeFile(
        path.join(fileDir, `${id}.json`),
        JSON.stringify({
          passwordHash,
          filename: path.basename(req.file.originalname),
        }),
        { flag: "wx", mode: 0o600 }
      );
    } catch (err) {
      await fs.rm(storedPath, { force: true });
      throw err;
    }

    res.json({ link: `/s/${id}` });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: "Upload failed." });
  } finally {
    if (tempPath) await fs.rm(tempPath, { force: true });
  }
});

const downloadLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 30,
  standardHeaders: true,
  legacyHeaders: false,
  message: "Too many attempts. Try again later.",
});

app.get("/s/:id", (req, res) => {
  if (!/^[a-f0-9]{48}$/.test(req.params.id)) {
    return res.sendStatus(404);
  }
  res.sendFile(path.join(__dirname, "public", "download.html"));
});

app.post("/download/:id", downloadLimiter, async (req, res) => {
  const { id } = req.params;
  const password = req.body.password;

  if (
    !/^[a-f0-9]{48}$/.test(id) ||
    typeof password !== "string" ||
    Buffer.byteLength(password, "utf8") > 72
  ) {
    return res.status(400).send("Invalid request.");
  }

  try {
    const metadata = JSON.parse(
      await fs.readFile(path.join(fileDir, `${id}.json`), "utf8")
    );

    if (!(await bcrypt.compare(password, metadata.passwordHash))) {
      return res.status(403).send("Incorrect password.");
    }

    res.download(path.join(fileDir, id), metadata.filename, (err) => {
      if (err && !res.headersSent) res.sendStatus(404);
    });
  } catch (err) {
    if (err.code === "ENOENT") return res.sendStatus(404);
    console.error(err);
    res.sendStatus(500);
  }
});

app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({ error: err.message });
  }
  console.error(err);
  res.status(500).json({ error: "Something went wrong." });
});

async function start() {
  await fs.mkdir(tempDir, { recursive: true });
  await fs.mkdir(fileDir, { recursive: true });
  app.listen(3000, () => console.log("Open http://localhost:3000"));
}

start().catch(console.error);
```

### 3. Create `public/index.html`

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Share a file</title>
</head>
<body>
  <h1>Share a file</h1>

  <form id="upload">
    <p><input type="file" name="file" required></p>
    <p>
      <label>
        Password:
        <input type="password" name="password" required>
      </label>
    </p>
    <button type="submit">Upload</button>
  </form>

  <p id="result"></p>

  <script>
    const form = document.querySelector("#upload");
    const result = document.querySelector("#result");

    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      result.textContent = "Uploading…";

      try {
        const response = await fetch("/upload", {
          method: "POST",
          body: new FormData(form)
        });
        const data = await response.json();

        if (!response.ok) throw new Error(data.error);

        const url = new URL(data.link, location.origin).href;
        result.textContent = "Share this link: ";
        const link = document.createElement("a");
        link.href = url;
        link.textContent = url;
        result.appendChild(link);
        form.reset();
      } catch (error) {
        result.textContent = error.message || "Upload failed.";
      }
    });
  </script>
</body>
</html>
```

### 4. Create `public/download.html`

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Download file</title>
</head>
<body>
  <h1>Download file</h1>
  <form id="download" method="post">
    <label>
      Password:
      <input type="password" name="password" required>
    </label>
    <button type="submit">Download</button>
  </form>

  <script>
    // The link ID selects the file; password verification happens on the server.
    const id = location.pathname.split("/").pop();
    document.querySelector("#download").action = "/download/" + encodeURIComponent(id);
  </script>
</body>
</html>
```

### 5. Run it

```bash
node server.js
```

Open `http://localhost:3000`, upload a file, and share the generated link. Send the password separately.

**Before exposing it to the internet:** use HTTPS, so passwords and files are encrypted in transit. The stored files themselves are not encrypted. This simple version also has no automatic expiry or storage quotas, and its rate limiter is per server process.

